namespace Tools::Vector{
    template<Numbers T>
    T Sum(const vec<T>& v){
        T result{};
        for(const auto x : v){
            result += x;
        }
        return result;
    }

    template<Numbers T>
    T Product(const vec<T>& v){
        T result{};
        for(const auto x : v){
            result *= x;
        }
        return result;
    }

    template <Numbers T>
    T Avg(const vec<T>& v){
        T sum = Sum(v);
        idx Size = v.size();

        return sum/Size;
    }
}

