template <typename T>
Tools::ivec<T> Tools::ivec<T>::operator*(const idx count) {
    Tools::ivec<T> Out;
    Out.reserve(this->IVecSize * count);

    for (idx i = 0; i < count; i++) {
        Out.extend(this);
    }

    return Out;
}





